/* ==========================================================================
   NUEVO: contador de stock restyleado + fila de pago (cuotas, garantia, pago
   seguro) + logos de tarjetas. Se ancla al cuadro de garantia existente para
   que el orden final quede siempre: STOCK -> LOGOS/PAGO -> GARANTIA (existente).
   Reemplaza el mensaje nativo "Quedan X unidades" por una tarjeta con la
   paleta de la marca.
   ========================================================================== */
(function() {
  if (window.WIGY_SLUG_BLOCK) return;
  var ID = "wigy-post-cta-trust";
  function svgOrPlaceholder(url, alt, fallbackHTML) {
    if (url && url.indexOf("PEGAR") === -1) {
      return '<img src="' + url + '" alt="' + alt + '">';
    }
    return fallbackHTML;
  }
  function mount() {
    if (document.getElementById(ID)) return true;
    var garantia = document.getElementById("wigy-garantia-box");
    var form = document.querySelector(".js-product-form") || document.getElementById("product_form");
    if (!garantia && !form) return false;
    if (!document.getElementById(ID + "-css")) {
      var st = document.createElement("style"); st.id = ID + "-css";
      st.innerHTML = "#" + ID + "{width:100%;max-width:640px;margin:0 auto 16px;box-sizing:border-box;font-family:inherit}#" + ID + " .pt-stock{border:1px solid rgba(0,0,0,.1);background:#f7f7f7;border-radius:12px;padding:14px 16px;margin-bottom:14px;box-sizing:border-box}#" + ID + " .pt-stock-label{display:flex;align-items:center;gap:6px;font-size:11px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;color:#111;margin:0 0 6px}#" + ID + " .pt-dot{width:7px;height:7px;border-radius:50%;background:#4ab25a;flex:0 0 auto}#" + ID + " .pt-stock-text{font-size:14.5px;font-weight:700;color:#111;margin:0 0 10px}#" + ID + " .pt-stock-text strong{color:#4ab25a;font-weight:900}#" + ID + " .pt-bar-track{width:100%;height:6px;border-radius:99px;background:rgba(74,178,90,.15);overflow:hidden}#" + ID + " .pt-bar-fill{height:100%;border-radius:99px;background:linear-gradient(90deg,#4ab25a,#27ae60)}#" + ID + " .pt-logos{display:flex;align-items:center;justify-content:center;gap:8px;margin-bottom:14px;flex-wrap:wrap}#" + ID + " .pt-chip{display:flex;align-items:center;justify-content:center;height:30px;padding:0 12px;border:1px solid #eee;border-radius:6px;background:#fff;box-shadow:0 1px 4px rgba(0,0,0,.05);overflow:hidden}#" + ID + " .pt-chip img{height:100%;width:auto;object-fit:contain}#" + ID + " .pt-chip-visa{font-family:Arial,sans-serif;font-style:italic;font-weight:900;font-size:14px;color:#1a1f71;letter-spacing:-.5px}#" + ID + " .pt-mc-circles{display:flex}#" + ID + " .pt-mc-circles span{width:14px;height:14px;border-radius:50%}#" + ID + " .pt-mc-circles span:first-child{background:#eb001b}#" + ID + " .pt-mc-circles span:last-child{background:#f79e1b;margin-left:-6px;opacity:.85}#" + ID + " .pt-chip-mp{background:#009ee3;border-color:#009ee3}#" + ID + " .pt-chip-mp span{color:#fff;font-weight:800;font-size:11px;letter-spacing:.2px;text-transform:lowercase}#" + ID + " .pt-feats{display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;text-align:center}#" + ID + " .pt-feat{display:flex;flex-direction:column;align-items:center;gap:6px}#" + ID + " .pt-feat svg{width:20px;height:20px;color:#111}#" + ID + " .pt-feat span{font-size:9.5px;font-weight:800;letter-spacing:.3px;color:#333;line-height:1.3;text-transform:uppercase}";
      document.head.appendChild(st);
    }
    // -- contador de stock: toma el numero del mensaje nativo de Tiendanube si existe --
    var stockHTML = "";
    var native = document.getElementById("js-urgency-last-units");
    if (native) {
      var txt = (native.textContent || "").trim();
      var m = txt.match(/(\d+)/);
      if (m) {
        var qty = m[1];
        var pct = Math.max(10, Math.min(90, (parseInt(qty, 10) / 20) * 100));
        stockHTML = '<div class="pt-stock"><p class="pt-stock-label"><span class="pt-dot"></span>Atencion</p><p class="pt-stock-text">Quedan <strong>' + qty + '</strong> unidades en stock</p><div class="pt-bar-track"><div class="pt-bar-fill" style="width:' + pct + '%"></div></div></div>';
      }
      native.style.cssText = "display:none!important";
    }
    // -- logos de pago: si hay URL cargada en WIGY_CONFIG.logosPago se usa la imagen, si no, chip generico --
    var lp = (window.WIGY_CONFIG && window.WIGY_CONFIG.logosPago) || {};
    var visaChip = '<div class="pt-chip pt-chip-visa">' + svgOrPlaceholder(lp.visa, "Visa", "VISA") + '</div>';
    var mcChip = '<div class="pt-chip">' + svgOrPlaceholder(lp.mastercard, "Mastercard", '<span class="pt-mc-circles"><span></span><span></span></span>') + '</div>';
    var mpChip = '<div class="pt-chip pt-chip-mp">' + svgOrPlaceholder(lp.mercadopago, "Mercado Pago", '<span>mercado pago</span>') + '</div>';
    var logosHTML = '<div class="pt-logos">' + visaChip + mcChip + mpChip + '</div>';
    var creditCardSvg = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="5" width="20" height="14" rx="2"/><line x1="2" y1="10" x2="22" y2="10"/></svg>';
    var shieldSvg = '<svg viewBox="0 0 24 24"><path fill="currentColor" d="M12 2l8 4v6c0 5-3.4 9.4-8 10-4.6-.6-8-5-8-10V6l8-4zm-1 14l6-6-1.4-1.4L11 13.2 8.4 10.6 7 12l4 4z"/></svg>';
    var lockSvg = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="5" y="11" width="14" height="10" rx="2"/><path d="M8 11V7a4 4 0 018 0v4"/></svg>';
    var featsHTML = '<div class="pt-feats"><div class="pt-feat">' + creditCardSvg + '<span>3 Cuotas<br>Sin Interes</span></div><div class="pt-feat">' + shieldSvg + '<span>30 Dias<br>De Garantia</span></div><div class="pt-feat">' + lockSvg + '<span>Pago Seguro<br>Mercado Pago</span></div></div>';
    var w = document.createElement("div"); w.id = ID;
    w.innerHTML = stockHTML + logosHTML + featsHTML;
    if (garantia) { garantia.insertAdjacentElement("beforebegin", w); } else { form.appendChild(w); }
    return true;
  }
  var tries = 0, t = setInterval(function() { tries++; if (mount() || tries >= 100) clearInterval(t); }, 200);
})();

