(function() {
  if (window.WIGY_SLUG_BLOCK) return;
  var ID = "wigy-social-toast";
  if (document.getElementById(ID + "-css")) return;
  var BUYERS = window.WIGY_CONFIG.compradoresToast || [];
  var TIMES = ["hace 2 min", "hace 4 min", "hace 7 min", "hace 11 min", "hace 15 min", "hace 20 min"];
  function pick(arr) { return arr[Math.floor(Math.random() * arr.length)]; }
  var css = "#" + ID + "{position:fixed;bottom:20px;left:20px;z-index:99999;max-width:300px;width:calc(100% - 40px);background:#fff;border-radius:12px;box-shadow:0 8px 30px rgba(0,0,0,.1);border:1px solid rgba(0,0,0,.06);padding:12px 14px;display:flex;align-items:center;gap:10px;font-family:inherit;transform:translateY(120%);opacity:0;transition:transform .45s cubic-bezier(.4,0,.2,1),opacity .4s;pointer-events:none}#" + ID + ".tin{transform:translateY(0);opacity:1;pointer-events:auto}#" + ID + ".tout{transform:translateY(120%);opacity:0;pointer-events:none}#" + ID + " .toast-avatar{width:40px;height:40px;border-radius:50%;background:linear-gradient(135deg,#4ab25a,#27ae60);display:flex;align-items:center;justify-content:center;flex:0 0 auto}#" + ID + " .ta span{color:#fff;font-size:16px;font-weight:800}#" + ID + " .toast-body{display:flex;flex-direction:column;gap:2px;min-width:0}#" + ID + " .toast-name{font-size:13px;font-weight:700;color:#111;line-height:1.3}#" + ID + " .toast-action{font-size:12px;color:#555;font-weight:500}#" + ID + " .toast-msg{font-size:11px;color:#999;font-weight:600}@media(min-width:769px){#" + ID + "{left:28px;bottom:24px;max-width:320px;width:320px}}";
  var st = document.createElement("style"); st.id = ID + "-css"; st.innerHTML = css; document.head.appendChild(st);
  var toast = document.createElement("div"); toast.id = ID; document.body.appendChild(toast);
  function getName() { var el = document.querySelector(".js-product-name") || document.querySelector("h1"); return el ? el.textContent.trim().substring(0, 30) : "2PM Post Lunch Performance"; }
  var count = 0;
  function show() {
    if (!BUYERS.length) return;
    var b = pick(BUYERS), ti = pick(TIMES), pn = getName();
    toast.innerHTML = '<div class="toast-avatar"><span>' + b.name.charAt(0).toUpperCase() + '</span></div><div class="toast-body"><span class="toast-name">' + b.name + ' de ' + b.city + '</span><span class="toast-action">Compro ' + pn + '</span><span class="toast-msg">' + ti + ' - Compra verificada</span></div>';
    toast.classList.remove("tin", "tout"); void toast.offsetWidth; toast.classList.add("tin");
    var dur = 4500 + (count * 3000); count++;
    setTimeout(function() { toast.classList.remove("tin"); toast.classList.add("tout"); }, dur);
    setTimeout(function() { show(); }, dur + 12000);
  }
  setTimeout(show, 8000);
})();

